'use strict';
const STORAGE_KEY='dumbo-demo-v3';
const categories=['Frutas y verduras','Lácteos','Panadería','Despensa','Bebidas'];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n);
const plural=(n,one='producto',many='productos')=>`${n} ${n===1?one:many}`;
function normalizePhone(v){const raw=String(v).trim();if(!/^[+\d\s()-]+$/.test(raw))return null;let digits=raw.replace(/\D/g,'');if(digits.startsWith('56')&&digits.length===11)digits=digits.slice(2);return /^[2-9]\d{8}$/.test(digits)?`+56 ${digits[0]} ${digits.slice(1,5)} ${digits.slice(5)}`:null}
function seedState(){return {products:[
{id:1,name:'Manzanas rojas',cat:categories[0],unit:'Bolsa 1 kg',price:1890,stock:24,photoId:1,sku:'FRU-001'},
{id:2,name:'Leche entera',cat:categories[1],unit:'Caja 1 litro',price:1190,stock:36,photoId:2,sku:'LAC-001'},
{id:3,name:'Pan de molde',cat:categories[2],unit:'Bolsa 500 g',price:2190,stock:18,photoId:3,sku:'PAN-001'},
{id:4,name:'Arroz grado 1',cat:categories[3],unit:'Bolsa 1 kg',price:1490,stock:42,photoId:4,sku:'DES-001'},
{id:5,name:'Plátanos',cat:categories[0],unit:'Bolsa 1 kg',price:1590,stock:20,photoId:5,sku:'FRU-002'},
{id:6,name:'Queso laminado',cat:categories[1],unit:'Paquete 250 g',price:3290,stock:12,photoId:6,sku:'LAC-002'},
{id:7,name:'Huevos',cat:categories[3],unit:'Caja 12 unidades',price:3690,stock:0,photoId:7,sku:'DES-002'},
{id:8,name:'Bebida naranja',cat:categories[4],unit:'Botella 1,5 litros',price:1790,stock:28,photoId:8,sku:'BEB-001'}],users:[
{id:1,names:'Camila',surname:'Rojas',email:'camila@example.com',phone:'+56 9 1234 5678',active:true},
{id:2,names:'Diego',surname:'Muñoz',email:'diego@example.com',phone:'+56 9 8765 4321',active:false},
{id:3,names:'Cliente',surname:'de demostración',email:'demo@example.com',phone:'+56 9 2345 6789',active:true}],staff:[
{id:4,names:'Valentina',surname:'Pérez',email:'valentina@example.com',phone:'+56 9 3456 7890',active:true}],cart:{},order:null,orderNumber:0,currentUserId:null,role:'cliente',search:'',category:'Todas',sort:'default'}}
function loadState(){try{const saved=JSON.parse(sessionStorage.getItem(STORAGE_KEY));if(saved&&Array.isArray(saved.products)&&Array.isArray(saved.users)&&Array.isArray(saved.staff)&&saved.cart)return saved}catch{}return seedState()}
let state=loadState();
for(const u of [...state.users,...state.staff])delete u.rut;
try{sessionStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{}
function commit(change){const previous=JSON.stringify(state);change();try{sessionStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true}catch{state=JSON.parse(previous);toast('No hay espacio para guardar la sesión. Usa una imagen de ejemplo o un archivo más pequeño.');return false}}
const product=id=>state.products.find(p=>p.id===Number(id));
const cartCount=()=>Object.values(state.cart).reduce((a,b)=>a+b,0);
const cartTotal=()=>state.products.reduce((a,p)=>a+p.price*(state.cart[p.id]||0),0);
const currentUser=()=>state.users.find(u=>u.id===state.currentUserId&&u.active&&!u.deleted);
const fullName=u=>`${u.names} ${u.surname}`;
const roleLinks={trabajador:[['inventario','Inventario'],['clientes','Clientes']],admin:[['inventario','Inventario'],['clientes','Clientes'],['trabajadores','Trabajadores'],['reportes','Reportes']]};
function toast(text){if(typeof dismissCartNotice==='function')dismissCartNotice();const el=$('#toast');clearTimeout(window.toastTimer);clearTimeout(window.toastHideTimer);el.textContent=text;el.style.display='block';void el.offsetWidth;el.classList.add('toast-visible');window.toastTimer=setTimeout(()=>{el.classList.remove('toast-visible');window.toastHideTimer=setTimeout(()=>el.style.display='none',180)},3200)}
function scrollTop(){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
function go(page){if(location.hash===`#${page}`)render();else location.hash=page}
function goClient(page){commit(()=>{state.role='cliente';if(page==='catalogo'){state.search='';state.category='Todas';state.catalogFilters={min:'',max:'',availability:'all',economy:false}}});go(page);scrollTop()}
function setCategory(cat){browseStoreCategory(cat)}
function productPhoto(p,extra=''){if(p.image)return `<img class="product-upload ${extra}" src="${esc(p.image)}" alt="${esc(p.name)}">`;if(p.photoId)return `<div class="product-photo photo-${p.photoId} ${extra}" role="img" aria-label="${esc(p.name)}"></div>`;return '<div class="no-product-photo">Sin imagen</div>'}
function render(){dismissCartNotice();let page=location.hash.slice(1)||'catalogo';const detailId=state.role==='cliente'&&/^producto\/\d+$/.test(page)?Number(page.split('/')[1]):null;const allowed=state.role==='cliente'?['catalogo','carrito','acceso','pago','confirmacion']:roleLinks[state.role]?.map(x=>x[0]);if(!allowed?.includes(page)&&detailId===null){go(state.role==='cliente'?'catalogo':'inventario');return}
renderWorkspaceChrome(page);
document.body.classList.toggle('storefront',state.role==='cliente');
$('#role').value=state.role;$('#cartcount').textContent=cartCount();$('#shopsearch').value=state.search;
$('#nav').innerHTML=state.role==='cliente'?['Todas',...categories].map(c=>`<button class="nav-category ${state.category===c&&page==='catalogo'?'active':''}" data-category="${esc(c)}" aria-pressed="${state.category===c&&page==='catalogo'}">${c==='Todas'?storeIcon('grid'):''}<span>${c==='Todas'?'Todos los productos':c}</span></button>`).join(''):roleLinks[state.role].map(([id,t])=>`<a href="#${id}" class="${id===page?'active':''}" ${id===page?'aria-current="page"':''}>${t}</a>`).join('');
$('#navigation-hint').textContent=state.role==='cliente'?'Desliza para ver más categorías':'Desliza para ver todas las secciones';
const views={catalogo,carrito,acceso,inventario,clientes:()=>people(false),trabajadores:()=>people(true),reportes,pago,confirmacion};$('#app').innerHTML=detailId!==null?renderStoreProduct(detailId):views[page]();bindPage(page);if(['catalogo','carrito'].includes(page)||detailId!==null)bindStorefront(page,detailId);syncStoreHeader();bindStoreHero();syncCartSuggestions(page);
}
function catalogo(){return renderCatalogPage()}
const pendingQuantities={};
function revealQuantity(id,scope){const p=product(id);if(p.stock<=(state.cart[id]||0))return;const picker=$(`#picker-${scope}-${id}`),trigger=$(`#open-picker-${scope}-${id}`),input=$(`#choose-${scope}-${id}`);document.querySelectorAll('.store-add-picker:not([hidden])').forEach(other=>{if(other===picker)return;other.hidden=true;const opener=$(`#open-${other.id}`);if(opener){opener.hidden=false;opener.setAttribute('aria-expanded','false')}});input.value=1;pendingQuantities[id]=1;checkSelection(id,scope);picker.hidden=false;trigger.hidden=true;trigger.setAttribute('aria-expanded','true');input.focus({preventScroll:true})}
function hideQuantity(id,scope){$(`#picker-${scope}-${id}`).hidden=true;const trigger=$(`#open-picker-${scope}-${id}`);trigger.hidden=false;trigger.setAttribute('aria-expanded','false');trigger.focus()}
function quantityPicker(p,scope){const remaining=Math.max(0,p.stock-(state.cart[p.id]||0)),value=remaining?Math.min(pendingQuantities[p.id]||1,remaining):0,id=`choose-${scope}-${p.id}`;return `<div class="quantity-picker"><label for="${id}">Cantidad<span class="sr-only"> de ${esc(p.name)}</span></label><div class="quantity-control"><button type="button" onclick="stepQuantity(${p.id},'${scope}',-1)" aria-label="Disminuir cantidad de ${esc(p.name)}" ${!remaining?'disabled':''}>−</button><input id="${id}" type="number" min="1" max="${remaining}" step="1" value="${value}" aria-describedby="${id}-error" onchange="checkSelection(${p.id},'${scope}')" ${!remaining?'disabled':''}><button type="button" onclick="stepQuantity(${p.id},'${scope}',1)" aria-label="Aumentar cantidad de ${esc(p.name)}" ${!remaining?'disabled':''}>+</button></div><p id="${id}-error" class="field-error" role="alert" hidden></p></div>`}
function checkSelection(id,scope){const input=$(`#choose-${scope}-${id}`),error=$(`#choose-${scope}-${id}-error`),remaining=Math.max(0,product(id).stock-(state.cart[id]||0)),n=Number(input.value);if(!Number.isInteger(n)||n<1||n>remaining){error.textContent=remaining?`Puedes agregar entre 1 y ${remaining} unidades.`:'Ya agregaste todo el stock disponible.';error.hidden=false;input.setAttribute('aria-invalid','true');return null}error.hidden=true;input.removeAttribute('aria-invalid');pendingQuantities[id]=n;return n}
function stepQuantity(id,scope,delta){const input=$(`#choose-${scope}-${id}`),remaining=Math.max(0,product(id).stock-(state.cart[id]||0));if(!remaining)return;const current=Number(input.value);input.value=Math.min(remaining,Math.max(1,(Number.isInteger(current)&&current>0?current:1)+delta));checkSelection(id,scope)}
function addSelected(id,scope){const quantity=checkSelection(id,scope);if(quantity!==null&&add(id,quantity)){const button=$(`#open-picker-${scope}-${id}`);if(scope==='suggest'){(button&&!button.disabled?button:$('#cart-suggestions-done')).focus({preventScroll:true});return}if(button&&!button.disabled)button.focus({preventScroll:true});storeNoticeReturnFocus=button&&!button.disabled?button:$('#cartcount').closest('a')}}
function add(id,quantity=1){const p=product(id);if(!p)return false;const remaining=p.stock-(state.cart[id]||0);if(!Number.isInteger(quantity)||quantity<1||quantity>remaining){toast('La cantidad no es válida o supera el stock disponible.');return false}const suggesting=Boolean($('#cart-suggestions')?.open);if(commit(()=>state.cart[id]=(state.cart[id]||0)+quantity)){render();pulseCart();if(suggesting)updateCartSuggestionAfterAdd(p,quantity);else showCartNotice(p,quantity);return true}return false}
function removeUnit(id){commit(()=>{if(state.cart[id]>1)state.cart[id]--;else delete state.cart[id]});render();pulseCart()}
function removeProduct(id){commit(()=>delete state.cart[id]);render();pulseCart();toast('Producto quitado del carrito.')}
function pulseCart(){const el=$('#cartcount');el.classList.remove('cart-updated');void el.offsetWidth;el.classList.add('cart-updated')}
let modalReturnFocus=null;
function openModal(html,titleId){modalReturnFocus=document.activeElement;const dialog=$('#modal');dialog.innerHTML=html;dialog.setAttribute('aria-labelledby',titleId);dialog.showModal();dialog.querySelector('input,select,button')?.focus()}
function closeModal(){$('#modal').close();modalReturnFocus?.isConnected&&modalReturnFocus.focus()}
function ask({title,text,action='Confirmar'}){
  return new Promise(resolve=>{
    const d=$('#confirmation'),returnFocus=document.activeElement;
    d.innerHTML='<h2 id="confirm-title">'+esc(title)+'</h2><p id="confirm-description">'+esc(text)+'</p><div class="dialog-actions"><button id="confirm-cancel" class="secondary">Cancelar</button><button id="confirm-accept">'+esc(action)+'</button></div>';
    d.setAttribute('aria-labelledby','confirm-title');d.setAttribute('aria-describedby','confirm-description');
    let closing=false,settled=false,result=false;
    const done=value=>{if(closing||settled)return;closing=true;result=value;d.close()};
    d.querySelector('#confirm-cancel').onclick=()=>done(false);
    d.querySelector('#confirm-accept').onclick=()=>done(true);
    d.oncancel=e=>{e.preventDefault();done(false)};
    d.onclose=()=>{if(settled)return;settled=true;d.oncancel=null;d.onclose=null;returnFocus?.isConnected&&returnFocus.focus();resolve(result)};
    d.showModal();d.querySelector('#confirm-cancel').focus();
  });
}
function detail(id){openStoreProduct(id)}
function receipt(button){return `<aside class="receipt"><div class="receipt-brand">dumbo</div><span class="eyebrow">Resumen de compra</span><div class="receipt-lines">${state.products.filter(p=>state.cart[p.id]).map(p=>`<div class="receipt-line"><span>${state.cart[p.id]} × ${esc(p.name)}</span><strong>${money(p.price*state.cart[p.id])}</strong></div>`).join('')}</div><div class="receipt-line"><span>${plural(cartCount())}</span><span>CLP</span></div><div class="receipt-total"><span>Total</span><strong>${money(cartTotal())}</strong></div><p class="muted receipt-note">Modalidad propuesta: retiro en tienda. Detalles por acordar con el equipo.</p>${button?`<button class="full" onclick="go(currentUser()?'pago':'acceso')">${currentUser()?'Continuar al pago':'Ingresar para continuar'}</button>`:''}</aside>`}
function setQuantity(id,value,input){const p=product(id),n=Number(value),error=$(`#qty-error-${id}`);if(!Number.isInteger(n)||n<1||n>p.stock){error.textContent=`Ingresa entre 1 y ${p.stock} unidades. Se mantuvo tu cantidad anterior.`;error.hidden=false;input.setAttribute('aria-invalid','true');input.value=state.cart[id];return}commit(()=>state.cart[id]=n);render();pulseCart()}
function field(scope,name,label,{value='',type='text',hint='',required=true,options=null}={}){const id=`${scope}-${name}`;return `<div class="field"><label for="${id}">${label}${required?' <span aria-hidden="true">*</span>':''}</label>${options?`<select id="${id}" name="${name}" aria-describedby="${id}-hint ${id}-error">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select>`:`<input id="${id}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} aria-describedby="${id}-hint ${id}-error" ${type==='email'?'autocomplete="email"':type==='tel'?'autocomplete="tel"':type==='password'?'autocomplete="off"':''}>`}<small id="${id}-hint">${hint}</small><p id="${id}-error" class="field-error" role="alert" hidden></p></div>`}
function clearErrors(form){form.querySelectorAll('.field-error,.form-error').forEach(e=>{e.textContent='';e.hidden=true});form.querySelectorAll('[aria-invalid]').forEach(e=>e.removeAttribute('aria-invalid'))}
function fieldError(form,name,text){const el=form.querySelector(`[name="${name}"]`);const error=form.querySelector(`#${el.id}-error`);error.textContent=text;error.hidden=false;el.setAttribute('aria-invalid','true')}
function showFormError(form,text){const error=form.querySelector('.form-error');error.textContent=text;error.hidden=false}
function formButtons(action){return `<p class="form-error" role="alert" hidden></p><div class="dialog-actions"><button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button type="submit">${action}</button></div>`}
function validatePerson(form,existingId=null){clearErrors(form);const data=Object.fromEntries(new FormData(form));let ok=true;for(const name of ['names','surname','email','phone']){data[name]=String(data[name]||'').trim();if(!data[name]){fieldError(form,name,'Completa este campo.');ok=false}}
if(data.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)){fieldError(form,'email','Ingresa un correo válido.');ok=false}const phone=normalizePhone(data.phone);if(data.phone&&!phone){fieldError(form,'phone','Usa 9 dígitos, por ejemplo 912345678, o +56 9 1234 5678.');ok=false}
const all=[...state.users,...state.staff].filter(u=>u.id!==existingId);if(data.email&&all.some(u=>u.email.toLowerCase()===data.email.toLowerCase())){fieldError(form,'email','Este correo ya está asociado a una cuenta, incluso si está eliminada. Gestión puede restaurarla.');ok=false}
if(!ok){form.querySelector('[aria-invalid="true"]')?.focus();return null}return {names:data.names,surname:data.surname,email:data.email.toLowerCase(),phone}}
function personFields(scope,u={}){return field(scope,'names','Nombres',{value:u.names})+field(scope,'surname','Apellidos',{value:u.surname})+field(scope,'email','Correo electrónico',{value:u.email,type:'email'})+field(scope,'phone','Teléfono',{value:u.phone,type:'tel',hint:'9 dígitos nacionales; también se acepta el prefijo +56.'})}
function nextUserId(){return Math.max(0,...state.users.map(u=>u.id),...state.staff.map(u=>u.id))+1}
function acceso(){const u=currentUser();if(u)return `<section class="formbox panel"><span class="eyebrow">Mi cuenta</span><h1>Hola, ${esc(u.names)}</h1><dl class="account-details"><dt>Nombre</dt><dd>${esc(fullName(u))}</dd><dt>Correo</dt><dd>${esc(u.email)}</dd><dt>Teléfono</dt><dd>${esc(u.phone)}</dd></dl><p class="notice">Sesión de demostración. No es una autenticación real.</p><button class="full" onclick="go('carrito')">Ver mi carrito</button><button class="secondary full" onclick="logout()">Cerrar sesión</button><div class="account-danger-zone"><h2>Eliminar cuenta</h2><p>Retira tu acceso sin borrar tus pedidos históricos.</p><button class="danger full" onclick="deleteAccount(false,${u.id},true)">Eliminar mi cuenta</button></div></section>`;return `<section class="formbox panel"><span class="eyebrow">Mi cuenta</span><h1>Ingresa o regístrate</h1><div class="formtabs" role="tablist" aria-label="Acceso a la cuenta"><button id="login-tab" role="tab" aria-selected="true" aria-controls="authform" onclick="authForm('login')">Ingresar</button><button id="register-tab" class="secondary" role="tab" aria-selected="false" aria-controls="authform" onclick="authForm('register')">Registrarse</button></div><div id="authform" role="tabpanel" aria-labelledby="login-tab"></div></section>`}
function authForm(mode){const register=mode==='register';$('#login-tab').setAttribute('aria-selected',!register);$('#register-tab').setAttribute('aria-selected',register);$('#authform').setAttribute('aria-labelledby',register?'register-tab':'login-tab');$('#authform').innerHTML=register?`<form id="registerform" novalidate>${personFields('register')}<p class="notice">Registro simulado sin RUT. En el sistema definitivo elegirás tu contraseña o recibirás un enlace de activación para un alta manual. Aquí no se guardan contraseñas.</p><p class="form-error" role="alert" hidden></p><button class="full" type="submit">Crear cuenta de ejemplo</button></form>`:`<form id="loginform" novalidate>${field('login','email','Correo electrónico',{type:'email'})}${field('login','password','Contraseña de ejemplo',{type:'password',hint:'Usa cualquier texto de ejemplo. No ingreses una contraseña real.'})}<p class="form-error" role="alert" hidden></p><button class="full" type="submit">Ingresar</button></form><button class="text-button" onclick="recover()">Olvidé mi contraseña</button><p class="notice">Prueba con <strong>demo@example.com</strong> y cualquier contraseña de ejemplo. Solo las cuentas habilitadas pueden ingresar.</p>`;
if(register)$('#registerform').onsubmit=async e=>{e.preventDefault();const form=e.target,data=validatePerson(form);if(!data)return;if(!await ask({title:'Confirmar registro',text:`Crear una cuenta de ejemplo para ${data.email}.`,action:'Crear cuenta'}))return;const id=nextUserId();if(!commit(()=>{state.users.push({...data,id,active:true});state.currentUserId=id})){showFormError(form,'No se pudo guardar la sesión.');return}go(cartCount()?'pago':'acceso');render();toast('Cuenta creada y disponible en gestión de clientes.')};else $('#loginform').onsubmit=e=>{e.preventDefault();const form=e.target;clearErrors(form);const email=form.querySelector('[name="email"]').value.trim().toLowerCase(),password=form.querySelector('[name="password"]').value.trim();if(!email){fieldError(form,'email','Ingresa tu correo.');return}if(!password){fieldError(form,'password','Ingresa una contraseña de ejemplo.');return}const u=state.users.find(u=>u.email===email&&!u.deleted);if(!u){showFormError(form,'Este correo no está registrado. Usa demo@example.com o crea una cuenta.');return}if(!u.active){showFormError(form,'Usuario deshabilitado.');return}commit(()=>state.currentUserId=u.id);go(cartCount()?'pago':'acceso');render()}}
function logout(){commit(()=>state.currentUserId=null);render();toast('Sesión de demostración cerrada.')}
function recover(){openModal(`<h2 id="recover-title">Recuperar contraseña</h2><form id="recoverform" novalidate>${field('recover','email','Correo electrónico',{type:'email'})}<p class="notice">Se mostrará el resultado de la solicitud, sin enviar correo real.</p>${formButtons('Enviar instrucciones')}</form>`,'recover-title');$('#recoverform').onsubmit=e=>{e.preventDefault();const form=e.target;clearErrors(form);const email=form.querySelector('input').value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){fieldError(form,'email','Ingresa un correo válido.');return}closeModal();toast('Solicitud simulada. No se envió un correo real.')}}
function personForm(isStaff,id){const list=isStaff?state.staff:state.users,u=list.find(u=>u.id===id);openModal(`<h2 id="person-title">${u?'Editar':'Registrar'} ${isStaff?'trabajador':'cliente'}</h2><form id="personform" novalidate>${personFields('person',u)}${formButtons('Guardar')}</form>`,'person-title');$('#personform').onsubmit=async e=>{e.preventDefault();const form=e.target,data=validatePerson(form,id);if(!data)return;if(!await ask({title:'Guardar datos',text:`Confirmar los datos de ${data.names} ${data.surname}.`,action:'Guardar cambios'}))return;if(!commit(()=>{if(u)Object.assign(u,data);else list.push({...data,id:nextUserId(),active:true})})){showFormError(form,'No se pudo guardar la sesión.');return}closeModal();render();toast('Datos guardados en la sesión de demostración.')}}
async function togglePerson(isStaff,id){const u=(isStaff?state.staff:state.users).find(u=>u.id===id),action=u.active?'Deshabilitar':'Habilitar';if(!await ask({title:`${action} cuenta`,text:`${action} el acceso de ${fullName(u)}.`,action}))return;commit(()=>{u.active=!u.active;if(!u.active&&state.currentUserId===id)state.currentUserId=null});render();toast('Estado de la cuenta actualizado.')}
function importView(){openModal(`<h2 id="import-title">Importar productos</h2><p>Columnas propuestas: SKU, nombre, categoría, presentación, precio y stock.</p><div class="field"><label for="importfile">Archivo Excel o CSV</label><input id="importfile" type="file" accept=".csv,.xlsx" aria-describedby="import-hint"><small id="import-hint">Selección de ejemplo; el archivo no se procesa.</small></div><p class="notice">Simulación: la vista previa utiliza filas de ejemplo, independientes del archivo seleccionado.</p><div class="dialog-actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button onclick="importPreview()">Ver ejemplo de validación</button></div>`,'import-title')}
function importPreview(){openModal(`<h2 id="import-preview-title">Validación de ejemplo</h2><p>3 filas revisadas: 2 válidas y 1 con error.</p><div class="tablewrap"><table><thead><tr><th scope="col">SKU</th><th scope="col">Resultado</th></tr></thead><tbody><tr><td>DES-010</td><td>Válido</td></tr><tr><td>BEB-010</td><td>Válido</td></tr><tr><td>LAC-010</td><td>Precio inválido</td></tr></tbody></table></div><p class="notice">Propuesta: rechazar el lote hasta corregir la fila inválida. No se han importado productos.</p><button onclick="closeModal()">Volver al inventario</button>`,'import-preview-title')}
async function pay(approved){const error=$('#payment-error');if(!approved){error.textContent='Pago rechazado de ejemplo. El carrito se mantiene; puedes reintentar.';error.hidden=false;return}if(!currentUser()||!cartCount()){go('carrito');return}const invalid=state.products.some(p=>(state.cart[p.id]||0)>p.stock);if(invalid){error.textContent='Cambió el stock. Revisa las cantidades de tu carrito antes de pagar.';error.hidden=false;return}if(!await ask({title:'Confirmar compra simulada',text:`Confirmar ${plural(cartCount())} por ${money(cartTotal())}. No se realizará ningún cobro.`,action:'Confirmar compra'}))return;if(!currentUser()||!cartCount()||state.products.some(p=>(state.cart[p.id]||0)>p.stock)){error.textContent='La compra cambió. Revisa el carrito.';error.hidden=false;return}if(!commit(()=>{state.orderNumber++;state.order={id:`DEMO-${String(state.orderNumber).padStart(4,'0')}`,amount:cartTotal(),units:cartCount(),items:state.products.filter(p=>state.cart[p.id]).map(p=>({name:p.name,qty:state.cart[p.id],price:p.price})),email:currentUser().email};state.products.forEach(p=>p.stock-=state.cart[p.id]||0);state.cart={}}))return;go('confirmacion');render();pulseCart()}
function confirmacion(){const o=state.order;if(!o||o.units<=0||o.amount<=0)return `<section class="empty-state panel"><h1>No hay una compra confirmada</h1><p>Prepara tu carrito para iniciar una compra de demostración.</p><button onclick="goClient('catalogo')">Volver al catálogo</button></section>`;return `${checkoutSteps(2)}<section class="success panel"><div class="check" aria-hidden="true">✓</div><span class="eyebrow">Compra simulada</span><h1>Tu pedido está confirmado</h1><p><strong>${esc(o.id)}</strong> · ${money(o.amount)} · ${plural(o.units)}</p><p class="muted">${esc(o.email)}</p><ul class="order-items">${o.items.map(i=>`<li>${i.qty} × ${esc(i.name)} <strong>${money(i.qty*i.price)}</strong></li>`).join('')}</ul><p class="notice">Demostración de retiro en tienda. No se generó una compra ni un pago real.</p><button onclick="goClient('catalogo')">Volver al catálogo</button></section>`}
const REPORTS={week:{start:'07/10/2026',end:'13/10/2026',label:'7 días',sales:[65000,71000,68000,88000,92000,124000,99000],labels:['07 oct','08 oct','09 oct','10 oct','11 oct','12 oct','13 oct'],purchases:44,milk:28,rice:21},month:{start:'14/09/2026',end:'13/10/2026',label:'30 días',sales:[490000,670000,580000,820000],labels:['14–20 sep','21–27 sep','28 sep–04 oct','05–13 oct'],purchases:185,milk:120,rice:95}};
let reportPeriod='week';
const pendingRecords=[{id:'R-101',reason:'SKU ausente',action:'Asignar el producto canónico antes de consolidar.'},{id:'R-102',reason:'Cantidad negativa',action:'Revisar el movimiento de origen.'},{id:'R-103',reason:'Fecha inválida',action:'Corregir la fecha de la transacción.'}];
function csvCell(v){return `"${String(v).replace(/"/g,'""')}"`}
function bindPage(page){if(page==='inventario')bindInventory();if(page==='catalogo')$('#sort').onchange=e=>{commit(()=>state.sort=e.target.value);render()};if(page==='carrito')document.querySelectorAll('[data-qty]').forEach(input=>input.onchange=()=>setQuantity(Number(input.dataset.qty),input.value,input));if(page==='acceso'&&!currentUser())authForm('login');if(page==='reportes')bindReport()}
$('#headersearch').onsubmit=e=>{e.preventDefault();const search=$('#shopsearch').value.trim();commit(()=>{state.search=search;state.category='Todas';state.role='cliente'});go('catalogo');scrollTop()};
$('#nav').onclick=e=>{const button=e.target.closest('[data-category]');if(button)setCategory(button.dataset.category)};
$('#role').onchange=e=>{commit(()=>state.role=e.target.value);go(state.role==='cliente'?'catalogo':'inventario');render();scrollTop()};
$('#modal').addEventListener('close',()=>{modalReturnFocus?.isConnected&&modalReturnFocus.focus()});
$('#back-top').onclick=e=>{e.preventDefault();scrollTop()};
window.addEventListener('hashchange',()=>{render();const app=$('#app');app.classList.remove('page-enter');void app.offsetWidth;app.classList.add('page-enter')});
